import {FIELD_NAMES,DEFAULT_COPY,newPolicy,formatNumber,validNumber,normalizeNumber,activeFields,validationErrors,buildMessage} from './core.mjs';
const $=id=>document.getElementById(id), STORAGE_KEY='dividend-line-helper.copy.v1';
let policies=[newPolicy()],copy={...DEFAULT_COPY},lastCopied='',toastTimer,undoState=null,showErrors=false;
try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved&&typeof saved==='object')for(const key of Object.keys(copy))if(typeof saved[key]==='string')copy[key]=saved[key];}catch{ $('save-status').textContent='無法讀取本機儲存；你仍可正常編輯與複製。'; }
function notify(message,undo=false){clearTimeout(toastTimer);const box=$('toast');box.replaceChildren(document.createTextNode(message));if(undo){const button=document.createElement('button');button.textContent='復原';button.onclick=()=>{if(undoState){policies=undoState;undoState=null;showErrors=false;renderPolicies();notify('已復原上一位客戶的資料');}};box.append(button);}box.hidden=false;toastTimer=setTimeout(()=>{box.hidden=true;},undo?12000:4500);}
function switchTab(name){for(const key of ['policies','copy']){const selected=key===name;$(key+'-tab').setAttribute('aria-selected',String(selected));$(key+'-tab').tabIndex=selected?0:-1;$(key+'-tab').classList.toggle('active',selected);$(key+'-panel').hidden=!selected;}}
for(const key of ['policies','copy']){$(key+'-tab').onclick=()=>switchTab(key);$(key+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'policies':e.key==='End'?'copy':key==='copy'?'policies':'copy';switchTab(next);$(next+'-tab').focus();}};}
function updatePreview(){const text=buildMessage(policies,copy);$('preview').textContent=text;$('char-count').textContent=Array.from(text).length.toLocaleString('zh-TW')+' 字';$('policy-count').textContent=policies.length;}
function saveCopy(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(copy));$('save-status').textContent='已儲存・共用文案保存在這個瀏覽器，不與其他夥伴同步。';}catch{$('save-status').textContent='此瀏覽器無法儲存；共用文案在關閉頁面後將不會保留。';}}
for(const key of Object.keys(copy)){$(key).value=copy[key];$(key).addEventListener('input',()=>{copy[key]=$(key).value;saveCopy();updatePreview();});}
function elem(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;}
function updateFieldError(input,error,p,key){const invalid=showErrors&&!validNumber(p[key]);input.setAttribute('aria-invalid',String(invalid));error.hidden=!invalid;error.textContent=normalizeNumber(p[key])===''?'請輸入數字（沒有時填 0）':'請輸入 0 或正數，可使用小數與千分位';}
function renderPolicies(){const container=$('policies');container.replaceChildren();policies.forEach((p,index)=>{const card=elem('article','policy-card');card.setAttribute('aria-label','保單 '+(index+1));const head=elem('div','policy-card-head');head.append(elem('span','policy-badge',String(index+1).padStart(2,'0')),elem('h3','', '保單資料'));if(policies.length>1){const remove=elem('button','remove-policy','× 移除');remove.setAttribute('aria-label','移除保單 '+(index+1));remove.onclick=async()=>{if(activeFields(p).some(key=>p[key]!=='')||p.name){if(!await confirmAction('移除這張保單？','這張保單的名稱與數字將會清除，其餘保單與共用文案會保留。'))return;}policies.splice(index,1);renderPolicies();$('add-policy').focus();};head.append(remove);}card.append(head);const nameId='name-'+index,nameLabel=elem('label','', '保單名稱');nameLabel.htmlFor=nameId;nameLabel.append(elem('span','optional','選填'));const name=elem('input');name.type='text';name.id=nameId;name.value=p.name;name.placeholder='例如：退休金保單、第二張保單';name.maxLength=100;name.autocomplete='off';name.oninput=()=>{p.name=name.value;updatePreview();};card.append(nameLabel,name);const types=elem('div','type-switch');types.setAttribute('role','group');types.setAttribute('aria-label','保單 '+(index+1)+' 回報格式');for(const [type,label]of [['income','每月領息'],['units','單位累積']]){const button=elem('button',p.type===type?'selected':'',label);button.setAttribute('aria-pressed',String(p.type===type));button.onclick=()=>{if(p.type===type)return;p.type=type;renderPolicies();container.children[index].querySelector('.type-switch .selected').focus();};types.append(button);}card.append(types);const grid=elem('div','number-grid');for(const key of activeFields(p)){const field=elem('div'),id=key+'-'+index,label=elem('label','field-label',FIELD_NAMES[key]);label.htmlFor=id;label.append(elem('span','', ['capital','value'].includes(key)?'（萬）':''));const wrap=elem('div','input-wrap'),input=elem('input');input.id=id;input.type='text';input.inputMode='decimal';input.autocomplete='off';input.spellcheck=false;input.maxLength=40;input.placeholder='0';input.value=validNumber(p[key])?formatNumber(p[key]):p[key];const error=elem('div','field-error');error.id=id+'-error';input.setAttribute('aria-describedby',error.id);updateFieldError(input,error,p,key);input.oninput=()=>{p[key]=input.value;updateFieldError(input,error,p,key);updatePreview();};input.onblur=()=>{if(validNumber(p[key]))input.value=formatNumber(p[key]);};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const inputs=[...container.querySelectorAll('.number-grid input')];const next=inputs[inputs.indexOf(input)+1];if(next)next.focus();else $('copy-message').focus();}};wrap.append(input,elem('span','unit',key==='units'?'單位':['capital','value'].includes(key)?'萬':'元'));field.append(label,wrap,error);grid.append(field);}card.append(grid);container.append(card);});updatePreview();}
$('add-policy').onclick=()=>{policies.push(newPolicy());renderPolicies();const card=$('policies').lastElementChild;card.scrollIntoView({behavior:'smooth',block:'nearest'});card.querySelector('input').focus({preventScroll:true});};
function confirmAction(title,description){$('confirm-title').textContent=title;$('confirm-description').textContent=description;return new Promise(resolve=>{const dialog=$('confirm-dialog');dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}
$('next-customer').onclick=async()=>{const dirty=policies.some(p=>p.name||['capital','value','income','total','units'].some(k=>p[k]!==''));if(dirty&&buildMessage(policies,copy)!==lastCopied){if(!await confirmAction('開始下一位客戶？','目前這份資料尚未複製，清空後可在提示訊息按「復原」。每月共用文案會保留。'))return;}undoState=structuredClone(policies);policies=[newPolicy()];showErrors=false;lastCopied='';renderPolicies();switchTab('policies');$('capital-0').focus();notify('已清空保單資料，共用文案已保留',true);};
async function writeClipboard(text){if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);return true;}catch{}}const box=elem('textarea');box.value=text;box.setAttribute('readonly','');box.style.cssText='position:fixed;top:0;left:0;width:1px;height:1px;opacity:0';document.body.append(box);box.focus();box.select();box.setSelectionRange(0,box.value.length);let result=false;try{result=document.execCommand('copy');}catch{}box.remove();$('copy-message').focus({preventScroll:true});return result;}
$('copy-message').onclick=async()=>{const errors=validationErrors(policies);if(errors.length){showErrors=true;renderPolicies();switchTab('policies');const first=errors[0];$(first.key+'-'+first.index).focus();notify('還有數字未填或格式不正確，請先完成標示欄位');return;}const text=buildMessage(policies,copy);if(await writeClipboard(text)){lastCopied=text;notify('已複製完整訊息，貼到 LINE 就完成了 ✓');}else{$('manual-text').value=text;$('manual-dialog').showModal();$('manual-text').focus();$('manual-text').select();$('manual-text').setSelectionRange(0,text.length);}};
$('help').onclick=()=>$('help-dialog').showModal();
renderPolicies();
